INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(3, 'Số 29 Nguyễn Bỉnh Khiêm, Hai Bà Trưng, Hà Nội ', , 'Bệnh viện Y học cổ truyền Trung ương ', '<p><strong>GIỚI THIỆU</strong></p>\n<p><strong>Địa chỉ:</strong> 29 Nguyễn Bỉnh Khiêm, Nguyễn Du, Hai Bà Trưng, Hà Nội</p>\n<p><strong>Thời gian làm việc:</strong></p>\n<ul>\n<li>Khoa khám bệnh làm việc cả ngày từ Thứ 2 - Thứ 6</li>\n<li>Từ 7h00 - 16h00 (người bệnh nên đăng ký khám trước 15h00)</li>\n</ul>\n<p>Bệnh viện Y học Cổ truyền Trung ương là bệnh viện đầu ngành về Y học cổ truyền - Trung tâm hợp tác về y học cổ truyền của Tổ chức Y tế thế giới tại Việt Nam. Bệnh viện có 34 khoa phòng và trung tâm được chia thành 4 khối: lâm sàng, cận lâm sàng, các trung tâm và khối các phòng ban chức năng.</p>\n<p>Bệnh viện có các khoa lâm sàng Nội, Ngoại, Phụ, Nội Nhi, Châm cứu dưỡng sinh, Lão, Hồi sức cấp cứu, Da liễu, Kiểm soát và Điều trị Ung bướu, Khám chữa bệnh tự nguyện chất lượng cao, Khoa khám bệnh, Khoa thận tiết niệu và nam học, Khoa đa khoa ngũ quan, Khoa cơ xương khớp; với đầy đủ các trang thiết bị hiện đại để phục vụ cho chẩn đoán, điều trị và nghiên cứu khoa học.</p>\n<p>Bệnh nhân được trực tiếp khám chữa bệnh là các Giáo sư, Phó giáo sư, Tiến sĩ, Thạc sĩ, BSCKI, BSCKII có chuyên môn cao, nhiều năm kinh nghiệm, là các chuyên gia đầu ngành trong lĩnh vực YHCT</p>\n', '**GIỚI THIỆU**\n\n**Địa chỉ:** 29 Nguyễn Bỉnh Khiêm, Nguyễn Du, Hai Bà Trưng, Hà Nội\n\n**Thời gian làm việc:**\n\n*   Khoa khám bệnh làm việc cả ngày từ Thứ 2 - Thứ 6\n*   Từ 7h00 - 16h00 (người bệnh nên đăng ký khám trước 15h00)\n\nBệnh viện Y học Cổ truyền Trung ương là bệnh viện đầu ngành về Y học cổ truyền - Trung tâm hợp tác về y học cổ truyền của Tổ chức Y tế thế giới tại Việt Nam. Bệnh viện có 34 khoa phòng và trung tâm được chia thành 4 khối: lâm sàng, cận lâm sàng, các trung tâm và khối các phòng ban chức năng.\n\nBệnh viện có các khoa lâm sàng Nội, Ngoại, Phụ, Nội Nhi, Châm cứu dưỡng sinh, Lão, Hồi sức cấp cứu, Da liễu, Kiểm soát và Điều trị Ung bướu, Khám chữa bệnh tự nguyện chất lượng cao, Khoa khám bệnh, Khoa thận tiết niệu và nam học, Khoa đa khoa ngũ quan, Khoa cơ xương khớp; với đầy đủ các trang thiết bị hiện đại để phục vụ cho chẩn đoán, điều trị và nghiên cứu khoa học.\n\nBệnh nhân được trực tiếp khám chữa bệnh là các Giáo sư, Phó giáo sư, Tiến sĩ, Thạc sĩ, BSCKI, BSCKII có chuyên môn cao, nhiều năm kinh nghiệm, là các chuyên gia đầu ngành trong lĩnh vực YHCT', '2023-12-14 22:48:09', '2023-12-14 22:48:09');
INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(4, '424 Đường 3/2, Phường 12, Quận 10, Thành phố Hồ Chí Minh', , 'Phòng khám Đa khoa Hạnh Phúc', '<p><strong>GIỚI THIỆU CHUNG</strong></p>\n<p>Chặng đường hơn 18 năm đồng hành cùng khách hàng trong hoạt động chăm sóc sức khỏe, với phương châm “Trao giá trị - nhận niềm tin”, lấy lợi ích của khách hàng làm phương châm cho mọi hành động. <strong>Phòng khám Đa khoa Hạnh Phúc</strong> không ngừng cải tiến nâng cao chất lượng dịch vụ, cam kết sẽ phục vụ quý khách ngày càng tốt hơn.</p>\n<p><strong>Phòng khám quy tụ đội ngũ bác sĩ ưu tú giàu kinh nghiệm và chuyên môn, đã và đang công tác tại các bệnh viện lớn như: Bệnh viện Đại học Y Dược TP. HCM, Bệnh viện Nhân dân Gia Định, Bệnh viện Tim Tâm Đức, Bệnh viện Từ Dũ.</strong></p>\n<ul>\n<li>Bác sĩ Chuyên khoa I Huỳnh Hữu Hạnh</li>\n<li>Giám đốc điều hành Phòng khám Đa khoa Hạnh Phúc</li>\n<li>Hơn 15 năm kinh nghiệm trong hoạt động khám và điều trị bệnh Tim mạch – Nội tiết – Tiêu hóa</li>\n<li>Nguyên bác sĩ khoa Nội Tim mạch - Bệnh viện Tim Tâm Đức</li>\n<li>Thạc sĩ, Bác sĩ Lê Minh Đông</li>\n<li>Giám đốc Y khoa Phòng khám Đa khoa Hạnh Phúc</li>\n<li>Hơn 25 năm trong hoạt động khám và điều trị bệnh lý Tim mạch – Tiêu hóa – Hô hấp</li>\n<li>Nguyên bác sĩ Nội khoa - Bệnh viện Nhân dân Gia Định</li>\n<li>Thạc sĩ, Bác sĩ Đặng Huỳnh Anh Thư</li>\n<li>Hơn 15 năm kinh nghiệm khám và điều trị bệnh Tim mạch – Hô hấp</li>\n<li>Bác sĩ điều trị chuyên khoa Tim mạch - Bệnh viện Đại học Y Dược TP. HCM</li>\n<li>Phó Trưởng bộ môn Sinh lý - Sinh lý bệnh Miễn dịch - Đại học Y Dược TP. HCM</li>\n<li>Bác sĩ Chuyên khoa I Lê Hồng Cúc</li>\n<li>40 năm kinh nghiệm khám và điều trị bệnh lý Sản phụ khoa</li>\n<li>Nguyên Trưởng khoa Sản - Bệnh viện Từ Dũ</li>\n<li>...</li>\n</ul>\n<p><strong>Trang thiết bị máy móc đáp ứng theo xu hướng hiện đại trong chẩn đoán và điều trị bệnh.</strong></p>\n<p><strong>Dịch vụ kỹ thuật chuyên môn được quản lý nghiêm ngặt bởi ban quản lý chất lượng giàu kinh nghiệm.</strong></p>\n', '**GIỚI THIỆU CHUNG**\n\nChặng đường hơn 18 năm đồng hành cùng khách hàng trong hoạt động chăm sóc sức khỏe, với phương châm “Trao giá trị - nhận niềm tin”, lấy lợi ích của khách hàng làm phương châm cho mọi hành động. **Phòng khám Đa khoa Hạnh Phúc** không ngừng cải tiến nâng cao chất lượng dịch vụ, cam kết sẽ phục vụ quý khách ngày càng tốt hơn.\n\n**Phòng khám quy tụ đội ngũ bác sĩ ưu tú giàu kinh nghiệm và chuyên môn, đã và đang công tác tại các bệnh viện lớn như: Bệnh viện Đại học Y Dược TP. HCM, Bệnh viện Nhân dân Gia Định, Bệnh viện Tim Tâm Đức, Bệnh viện Từ Dũ.**\n\n*   Bác sĩ Chuyên khoa I Huỳnh Hữu Hạnh\n*   Giám đốc điều hành Phòng khám Đa khoa Hạnh Phúc\n*   Hơn 15 năm kinh nghiệm trong hoạt động khám và điều trị bệnh Tim mạch – Nội tiết – Tiêu hóa\n*   Nguyên bác sĩ khoa Nội Tim mạch - Bệnh viện Tim Tâm Đức\n*   Thạc sĩ, Bác sĩ Lê Minh Đông\n*   Giám đốc Y khoa Phòng khám Đa khoa Hạnh Phúc\n*   Hơn 25 năm trong hoạt động khám và điều trị bệnh lý Tim mạch – Tiêu hóa – Hô hấp\n*   Nguyên bác sĩ Nội khoa - Bệnh viện Nhân dân Gia Định\n*   Thạc sĩ, Bác sĩ Đặng Huỳnh Anh Thư\n*   Hơn 15 năm kinh nghiệm khám và điều trị bệnh Tim mạch – Hô hấp\n*   Bác sĩ điều trị chuyên khoa Tim mạch - Bệnh viện Đại học Y Dược TP. HCM\n*   Phó Trưởng bộ môn Sinh lý - Sinh lý bệnh Miễn dịch - Đại học Y Dược TP. HCM\n*   Bác sĩ Chuyên khoa I Lê Hồng Cúc\n*   40 năm kinh nghiệm khám và điều trị bệnh lý Sản phụ khoa\n*   Nguyên Trưởng khoa Sản - Bệnh viện Từ Dũ\n*   ...\n\n**Trang thiết bị máy móc đáp ứng theo xu hướng hiện đại trong chẩn đoán và điều trị bệnh.**\n\n**Dịch vụ kỹ thuật chuyên môn được quản lý nghiêm ngặt bởi ban quản lý chất lượng giàu kinh nghiệm.**', '2023-12-14 22:52:04', '2023-12-14 22:52:04');
INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(5, '72 Nguyễn Chí Thanh, Phường Láng Thượng, Đống Đa, Hà Nội', , 'Bệnh viện Mắt Hà Nội 2', '<p><strong>GIỚI THIỆU CHUNG</strong></p>\n<p><strong>Bệnh viện Mắt Hà Nội 2</strong> được thành lập từ năm 2017, hiện đã và đang là một trong những bệnh viện chuyên khoa Mắt hàng đầu Việt Nam với chuyên môn lâm sàng, quy trình khám và điều trị khắt khe, đảm bảo tiêu chuẩn an toàn tốt nhất cho bệnh nhân. Mắt Hà Nội 2 tự hào là một trong số các bệnh viện đầu tiên ngoài nước Pháp triển khai tiêu chuẩn quản lý chất lượng HAS nghiêm ngặt bậc nhất Thế giới. Và là cơ sở thực hành của Đại học Y Hà Nội, thực hiện đào tạo bác sĩ, chuyên gia nhãn khoa cho cả nước.</p>\n<p><strong>Đội ngũ y bác sĩ có chuyên môn sâu về nhãn khoa, là các chuyên gia hàng đầu trên toàn quốc và trong khu vực.</strong></p>\n<ul>\n<li>Phó Giáo sư, Tiến sĩ Hoàng Thị Minh Châu</li>\n<li>40 năm kinh nghiệm trong khám và điều trị các bệnh lý về mắt</li>\n<li>Nguyên Phó Giám đốc Bệnh viện Mắt Trung ương</li>\n<li>Phó Chủ tịch Hội Nhãn khoa Việt Nam</li>\n<li>Phó Giáo sư, Tiến sĩ Nguyễn Đức Anh</li>\n<li>Trên 35 năm kinh nghiệm chuyên môn</li>\n<li>Giảng viên nhãn khoa tại viện Karolinska (Thụy Điển)</li>\n<li>Giảng viên cao cấp bộ môn Mắt trường Đại học Y Hà Nội</li>\n<li>Thạc sĩ, Bác sĩ Mai Thị Anh Thư</li>\n<li>10 năm kinh nghiệm trong ngành nhãn khoa</li>\n<li>Trưởng Khoa Khám bệnh - Bệnh viện Mắt Hà Nội 2</li>\n<li>Bác sĩ Chuyên khoa I Nguyễn Thị Thúy Nga</li>\n<li>Gần 20 năm kinh nghiệm trong ngành nhãn khoa</li>\n<li>Phó Trưởng khoa Khúc xạ - Bệnh viện Mắt Hà Nội 2</li>\n</ul>\n<p><strong>Bệnh viện Mắt Hà Nội 2 quyết tâm xây dựng một cơ sở bệnh viện cùng hệ thống trang thiết bị hiện đại nhất thế giới ngay tại Hà Nội.</strong></p>\n', '**GIỚI THIỆU CHUNG**\n\n**Bệnh viện Mắt Hà Nội 2** được thành lập từ năm 2017, hiện đã và đang là một trong những bệnh viện chuyên khoa Mắt hàng đầu Việt Nam với chuyên môn lâm sàng, quy trình khám và điều trị khắt khe, đảm bảo tiêu chuẩn an toàn tốt nhất cho bệnh nhân. Mắt Hà Nội 2 tự hào là một trong số các bệnh viện đầu tiên ngoài nước Pháp triển khai tiêu chuẩn quản lý chất lượng HAS nghiêm ngặt bậc nhất Thế giới. Và là cơ sở thực hành của Đại học Y Hà Nội, thực hiện đào tạo bác sĩ, chuyên gia nhãn khoa cho cả nước.\n\n**Đội ngũ y bác sĩ có chuyên môn sâu về nhãn khoa, là các chuyên gia hàng đầu trên toàn quốc và trong khu vực.**\n\n*   Phó Giáo sư, Tiến sĩ Hoàng Thị Minh Châu\n*   40 năm kinh nghiệm trong khám và điều trị các bệnh lý về mắt\n*   Nguyên Phó Giám đốc Bệnh viện Mắt Trung ương\n*   Phó Chủ tịch Hội Nhãn khoa Việt Nam\n*   Phó Giáo sư, Tiến sĩ Nguyễn Đức Anh\n*   Trên 35 năm kinh nghiệm chuyên môn\n*   Giảng viên nhãn khoa tại viện Karolinska (Thụy Điển)\n*   Giảng viên cao cấp bộ môn Mắt trường Đại học Y Hà Nội\n*   Thạc sĩ, Bác sĩ Mai Thị Anh Thư\n*   10 năm kinh nghiệm trong ngành nhãn khoa\n*   Trưởng Khoa Khám bệnh - Bệnh viện Mắt Hà Nội 2\n*   Bác sĩ Chuyên khoa I Nguyễn Thị Thúy Nga\n*   Gần 20 năm kinh nghiệm trong ngành nhãn khoa\n*   Phó Trưởng khoa Khúc xạ - Bệnh viện Mắt Hà Nội 2\n\n**Bệnh viện Mắt Hà Nội 2 quyết tâm xây dựng một cơ sở bệnh viện cùng hệ thống trang thiết bị hiện đại nhất thế giới ngay tại Hà Nội.**', '2023-12-14 22:53:26', '2023-12-14 22:53:26');
INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(6, '29 Hàn Thuyên, Phạm Đình Hổ, Hai Bà Trưng, Hà Nội', , 'Bệnh viện Đa khoa Hà Nội', '<p><strong>GIỚI THIỆU CHUNG</strong></p>\n<p>Bệnh viện Đa khoa Hà Nội được hình thành từ năm 1910 trên cơ sở Bệnh viện tỉnh Hà Tây cũ. Từ tháng 8/2008, Bệnh viện được đổi tên là Bệnh viện Đa khoa Hà Nội, thuộc Sở Y tế Hà Nội và trở thành một trong ba Bệnh viện đa khoa hạng I của Thủ đô. Là Bệnh viện vệ tinh của Bệnh viện Bạch Mai, Bệnh viện Tim Hà Nội.</p>\n<p><strong>Khu khám dịch vụ tự nguyện với đội ngũ bác sĩ là những bác sĩ đã nhiều năm hoạt động trong nghề, giàu kinh nghiệm, trình độ chuyên môn cao:</strong></p>\n<ul>\n<li>Phó Giáo sư, Tiến sĩ Mai Xuân Hiên: 50 năm công tác trong ngành y tế, Nguyên chủ nhiệm bộ môn, Khoa Hồi sức cấp cứu Học viện Quân y 103</li>\n<li>Thầy thuốc ưu tú, Thạc sĩ Vũ Đình Thám: 38 năm kinh nghiệm khám chữa bệnh Da liễu, Nguyễn Trưởng khoa Da liễu Bệnh viện Đại học Y Thái Bình</li>\n<li>Thầy thuốc ưu tú, Bác sĩ Chuyên khoa II Trần Ngọc Cường: Hơn 35 năm kinh nghiệm trong lĩnh vực Sản Phụ khoa, Nguyên Trưởng khoa Phụ Sản Bệnh viện Đa khoa Hà Đông</li>\n<li>Bác sĩ Chuyên khoa II Trần Văn Đăng: 25 năm kinh nghiệm khám chữa bệnh chuyên khoa Nội, Trưởng Đơn nguyên khám chữa bệnh tự nguyện - Bệnh viện Đa khoa Hà Nội</li>\n</ul>\n<p><strong>Bệnh viện đầu tư cơ sở vật chất, thiết bị y tế và hệ thống máy móc hiện đại được nhập khẩu từ các nước lớn trên thế giới, nhằm đảm bảo việc khám lâm sàng và điều trị bệnh được chính xác và an toàn.</strong></p>\n', '**GIỚI THIỆU CHUNG**\n\nBệnh viện Đa khoa Hà Nội được hình thành từ năm 1910 trên cơ sở Bệnh viện tỉnh Hà Tây cũ. Từ tháng 8/2008, Bệnh viện được đổi tên là Bệnh viện Đa khoa Hà Nội, thuộc Sở Y tế Hà Nội và trở thành một trong ba Bệnh viện đa khoa hạng I của Thủ đô. Là Bệnh viện vệ tinh của Bệnh viện Bạch Mai, Bệnh viện Tim Hà Nội.\n\n**Khu khám dịch vụ tự nguyện với đội ngũ bác sĩ là những bác sĩ đã nhiều năm hoạt động trong nghề, giàu kinh nghiệm, trình độ chuyên môn cao:**\n\n*   Phó Giáo sư, Tiến sĩ Mai Xuân Hiên: 50 năm công tác trong ngành y tế, Nguyên chủ nhiệm bộ môn, Khoa Hồi sức cấp cứu Học viện Quân y 103\n*   Thầy thuốc ưu tú, Thạc sĩ Vũ Đình Thám: 38 năm kinh nghiệm khám chữa bệnh Da liễu, Nguyễn Trưởng khoa Da liễu Bệnh viện Đại học Y Thái Bình\n*   Thầy thuốc ưu tú, Bác sĩ Chuyên khoa II Trần Ngọc Cường: Hơn 35 năm kinh nghiệm trong lĩnh vực Sản Phụ khoa, Nguyên Trưởng khoa Phụ Sản Bệnh viện Đa khoa Hà Đông\n*   Bác sĩ Chuyên khoa II Trần Văn Đăng: 25 năm kinh nghiệm khám chữa bệnh chuyên khoa Nội, Trưởng Đơn nguyên khám chữa bệnh tự nguyện - Bệnh viện Đa khoa Hà Nội\n\n**Bệnh viện đầu tư cơ sở vật chất, thiết bị y tế và hệ thống máy móc hiện đại được nhập khẩu từ các nước lớn trên thế giới, nhằm đảm bảo việc khám lâm sàng và điều trị bệnh được chính xác và an toàn.**', '2023-12-14 22:56:07', '2023-12-14 22:56:07');
INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(7, '54 Nguyễn Xiển, Thanh Xuân, Hà Nội', , 'Hệ thống Phòng khám Da liễu Hà Nội', '<p><strong>GIỚI THIỆU CHUNG</strong></p>\n<p><strong>Phòng khám Da liễu Hà Nội</strong> được thành lập từ năm 2010 do Sở Y tế cấp phép hoạt động.</p>\n<p><strong>Phòng khám có thế mạnh về Trị mụn y khoa, trị thâm do mụn, trị sẹo rỗ sau mụn</strong></p>\n<p><strong>Các bác sĩ tại phòng khám có kinh nghiệm và chuyên môn cao sẽ trực tiếp thăm khám, lên phác đồ điều trị và trực tiếp trị liệu cho bệnh nhân</strong></p>\n<p><strong>Quy trình trị liệu chuẩn y khoa:</strong></p>\n<ul>\n<li>Mỗi khách hàng trước tiến hành điều trị sẽ được Bác sĩ thăm khám, xem xét mức độ tình trạng của từng bệnh nhân để lên phác đồ điều trị hiệu quả và phù hợp với cơ địa</li>\n<li>Các dụng cụ và phòng trị liệu của phòng khám luôn được vệ sinh và tiệt trùng sạch sẽ</li>\n<li>Các sản phẩm được sử dụng trong trị liệu có nguồn gốc xuất xứ rõ ràng, được sự kiểm chứng chất lượng của Bộ Y tế về an toàn và hiệu quả</li>\n</ul>\n<p><strong>Hệ thống trang thiết bị hiện đại đồng bộ phục vụ cho công tác chẩn đoán và điều trị hiệu quả</strong></p>\n<ul>\n<li>Công nghệ Elight 3S, Sử dụng năng lượng IPL, Máy M90e</li>\n<li>Công nghệ Biolight, Sử dụng năng lượng ánh sáng sinh học</li>\n<li>Công nghệ Plasma lạnh</li>\n<li>Công nghệ Laser Hellios III</li>\n<li>Công nghệ DPL, sử dụng năng lượng DPL</li>\n</ul>\n', '**GIỚI THIỆU CHUNG**\n\n**Phòng khám Da liễu Hà Nội** được thành lập từ năm 2010 do Sở Y tế cấp phép hoạt động.\n\n**Phòng khám có thế mạnh về Trị mụn y khoa, trị thâm do mụn, trị sẹo rỗ sau mụn**\n\n**Các bác sĩ tại phòng khám có kinh nghiệm và chuyên môn cao sẽ trực tiếp thăm khám, lên phác đồ điều trị và trực tiếp trị liệu cho bệnh nhân**\n\n**Quy trình trị liệu chuẩn y khoa:**\n\n*   Mỗi khách hàng trước tiến hành điều trị sẽ được Bác sĩ thăm khám, xem xét mức độ tình trạng của từng bệnh nhân để lên phác đồ điều trị hiệu quả và phù hợp với cơ địa\n*   Các dụng cụ và phòng trị liệu của phòng khám luôn được vệ sinh và tiệt trùng sạch sẽ\n*   Các sản phẩm được sử dụng trong trị liệu có nguồn gốc xuất xứ rõ ràng, được sự kiểm chứng chất lượng của Bộ Y tế về an toàn và hiệu quả \n\n**Hệ thống trang thiết bị hiện đại đồng bộ phục vụ cho công tác chẩn đoán và điều trị hiệu quả**\n\n*   Công nghệ Elight 3S, Sử dụng năng lượng IPL, Máy M90e\n*   Công nghệ Biolight, Sử dụng năng lượng ánh sáng sinh học\n*   Công nghệ Plasma lạnh\n*   Công nghệ Laser Hellios III\n*   Công nghệ DPL, sử dụng năng lượng DPL', '2023-12-14 23:00:30', '2023-12-14 23:00:30');
INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(8, '103 Đường 37, Khu đô thị Vạn Phúc, P.Hiệp Bình Phước, Thủ Đức, HCM', , 'Trung tâm Y khoa MIC Vietnam', '<p><strong>GIỚI THIỆU CHUNG</strong></p>\n<p><strong>Trung tâm Y khoa MIC Vietnam</strong> chuyên cung cấp dịch vụ xét nghiệm từ cơ bản đến nâng cao, nhanh chóng và chính xác. Trung tâm MIC luôn mang trong mình sứ mệnh mới – mang đến cho quý khách dịch vụ chăm sóc sức khỏe chủ động toàn diện và hiệu quả hơn bằng giải pháp công nghệ mới, hiện đại chuẩn y khoa. Khách hàng đến với MIC sẽ được chăm sóc sức khỏe toàn diện trong không gian “Chất lượng xanh”.</p>\n<p>Lợi thế của MIC:</p>\n<ul>\n<li>Dịch vụ đa dạng, khách hàng có thể lựa chọn thực hiện các gói xét nghiệm của trung tâm: xét nghiệm tổng quát, lấy mẫu tại nhà, tầm soát ung thư, gói khám doanh nghiệp</li>\n<li>Đội ngũ nhân sự giỏi, nhiều năm kinh nghiệm trong lĩnh vực y tế</li>\n<li><strong>Công nghệ hàng đầu thế giới:</strong> Sở hữu công nghệ tiên tiến đáp ứng mọi nhu cầu xét nghiệm, đạt chuẩn quốc tế, nhập khẩu 100% từ Đức, Nhật, Mỹ, Hàn,… cho ra kết quả nhanh chóng, chuẩn xác</li>\n<li>Tiết kiệm thời gian</li>\n<li>Nhận kết quả online</li>\n<li>Chi phí hợp lý</li>\n<li>Tư vấn không giới hạn bởi các kĩ thuật viên của Trung tâm</li>\n</ul>\n', '**GIỚI THIỆU CHUNG**\n\n**Trung tâm Y khoa MIC Vietnam** chuyên cung cấp dịch vụ xét nghiệm từ cơ bản đến nâng cao, nhanh chóng và chính xác. Trung tâm MIC luôn mang trong mình sứ mệnh mới – mang đến cho quý khách dịch vụ chăm sóc sức khỏe chủ động toàn diện và hiệu quả hơn bằng giải pháp công nghệ mới, hiện đại chuẩn y khoa. Khách hàng đến với MIC sẽ được chăm sóc sức khỏe toàn diện trong không gian “Chất lượng xanh”.\n\nLợi thế của MIC:\n\n*   Dịch vụ đa dạng, khách hàng có thể lựa chọn thực hiện các gói xét nghiệm của trung tâm: xét nghiệm tổng quát, lấy mẫu tại nhà, tầm soát ung thư, gói khám doanh nghiệp\n*   Đội ngũ nhân sự giỏi, nhiều năm kinh nghiệm trong lĩnh vực y tế\n*   **Công nghệ hàng đầu thế giới:** Sở hữu công nghệ tiên tiến đáp ứng mọi nhu cầu xét nghiệm, đạt chuẩn quốc tế, nhập khẩu 100% từ Đức, Nhật, Mỹ, Hàn,… cho ra kết quả nhanh chóng, chuẩn xác\n*   Tiết kiệm thời gian\n*   Nhận kết quả online\n*   Chi phí hợp lý\n*   Tư vấn không giới hạn bởi các kĩ thuật viên của Trung tâm', '2023-12-14 23:12:57', '2023-12-14 23:12:57');
INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(9, '476B Nguyễn Tri Phương, Phường 9, Quận 10, Hồ Chí Minh', , 'Phòng khám Quốc tế Phổi Sài Gòn', '<p><strong>GIỚI THIỆU CHUNG</strong></p>\n<p>Phòng Khám Chuyên Khoa Quốc Tế Phổi Sài Gòn là nơi hội tụ những Bác sĩ tâm huyết trong chuyên ngành Bệnh Phổi &amp; Lao, các bác sĩ đều có kinh nghiệm điều trị trên 20 năm tại bệnh viện chuyên khoa tuyến đầu cả nước, được đào tạo chính quy, bài bản tại Đại Học Y Dược Thành Phố Hồ Chi Minh.</p>\n<p><strong>Đội ngũ bác sĩ giỏi, giàu kinh nghiệm trong khám và điều trị chuyên ngành Bệnh Phổi và Lao</strong></p>\n<ul>\n<li>Bác sĩ Chuyên khoa II Lê Hồng Anh - Hơn 20 năm kinh nghiệm trong lĩnh vực Hô hấp - Phổi -Lao; Giám đốc chuyên môn Phòng khám; Bác sĩ công tác nhiều năm tại Bệnh viện Phạm Ngọc Thạch</li>\n<li>Bác sĩ Chuyên khoa II Nguyễn Văn Hoạch - Hơn 20 năm kinh nghiệm trong lĩnh vực Phổi và Lao; Trưởng khoa Điều trị, Bệnh viện Phạm Ngọc Thạch</li>\n</ul>\n<p><strong>Phòng khám Phổi Sài Gòn đầu tư trang thiết bị, máy móc hiện đại, hỗ trợ thực hiện các chụp chiếu, các kỹ thuật trong thăm khám và thăm dò chức năng hô hấp</strong></p>\n<ul>\n<li>Máy chụp X-quang</li>\n<li>Máy đo chức năng hô hấp</li>\n<li>Máy chụp cắt lớp vi tính CT scan</li>\n<li>Máy nội soi ống mềm</li>\n</ul>\n', '**GIỚI THIỆU CHUNG**\n\nPhòng Khám Chuyên Khoa Quốc Tế Phổi Sài Gòn là nơi hội tụ những Bác sĩ tâm huyết trong chuyên ngành Bệnh Phổi & Lao, các bác sĩ đều có kinh nghiệm điều trị trên 20 năm tại bệnh viện chuyên khoa tuyến đầu cả nước, được đào tạo chính quy, bài bản tại Đại Học Y Dược Thành Phố Hồ Chi Minh.\n\n**Đội ngũ bác sĩ giỏi, giàu kinh nghiệm trong khám và điều trị chuyên ngành Bệnh Phổi và Lao**\n\n*   Bác sĩ Chuyên khoa II Lê Hồng Anh - Hơn 20 năm kinh nghiệm trong lĩnh vực Hô hấp - Phổi -Lao; Giám đốc chuyên môn Phòng khám; Bác sĩ công tác nhiều năm tại Bệnh viện Phạm Ngọc Thạch\n*   Bác sĩ Chuyên khoa II Nguyễn Văn Hoạch - Hơn 20 năm kinh nghiệm trong lĩnh vực Phổi và Lao; Trưởng khoa Điều trị, Bệnh viện Phạm Ngọc Thạch\n\n**Phòng khám Phổi Sài Gòn đầu tư trang thiết bị, máy móc hiện đại, hỗ trợ thực hiện các chụp chiếu, các kỹ thuật trong thăm khám và thăm dò chức năng hô hấp**\n\n*   Máy chụp X-quang\n*   Máy đo chức năng hô hấp\n*   Máy chụp cắt lớp vi tính CT scan\n*   Máy nội soi ống mềm', '2023-12-14 23:14:59', '2023-12-14 23:14:59');
INSERT INTO `clinics` (`id`, `address`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(10, '20-20-22 Đinh Tiên Hoàng, Phường Đa Kao, Quận 1, TP. HCM', , 'Phòng khám Đa khoa Victoria Healthcare', '<p><strong>GIỚI THIỆU CHUNG</strong></p>\n<p><strong>Phòng khám Đa khoa Victoria Healthcare</strong> thành lập từ năm 2005 đến nay đã trải qua chiều dài kinh nghiệm trong lĩnh vực chăm sóc sức khỏe y tế cao cấp và tạo được sự tín nhiệm cao đối với khách hàng trong khu vực TP Hồ Chí Minh cũng như các tỉnh lân cận. Tại Victoria Healthcare, các Bác sĩ đều nhấn mạnh tầm quan trọng của phương pháp “y học chứng cứ” các tiến trình chẩn đoán và điều trị phải dựa trên xác nhận của y văn hoặc kinh nghiệm điều trị thực tế đã được kiểm chứng, tránh việc lạm dụng thuốc và xét nghiệm. Bác sĩ của Phòng khám phải có nghĩa vụ và trách nhiệm tư vấn thấu đáo cho bệnh nhân cùng gia đình về nguồn gốc, nguyên nhân bệnh, cách chữa trị và phương pháp phòng ngừa. Đó chính là cốt lõi của việc chăm sóc sức khỏe theo tiêu chuẩn Quốc tế.</p>\n<p>Hệ thống phòng khám Victoria Healthcare có nhiều chi nhánh tại các vị trí giao thông thuận tiện trong thành phố, đầy đủ các chuyên khoa, phục vụ chức năng thăm khám và điều trị ngoại trú.</p>\n<p><strong>Đội ngũ y bác sĩ năng động, tâm huyết, nhiều năm kinh nghiệm, được liên tục đào tạo tại Mỹ, Úc, Nhật… và cam kết thực hành y khoa trên nền tảng Y học chứng cứ.</strong></p>\n<ul>\n<li>Bác sĩ chuyên khoa II Nguyễn Thị Băng Hải</li>\n<li>40 năm kinh nghiệm lĩnh vực Sản phụ khoa</li>\n<li>Từng công tác tại Bệnh viện Đại học Y Dược TP. Hồ Chí Minh, Bệnh viện Đa khoa Vạn Hạnh</li>\n<li>Bác sĩ Chuyên khoa I Bùi Bảo Thành</li>\n<li>15 năm kinh nghiệm lĩnh vực Nội Tim mạch</li>\n<li>Bác sĩ chuyên khoa Nội Tim Mạch - Viện Tim TP. HCM</li>\n<li>Thạc sĩ, Bác sĩ Nội trú Nguyễn Cảnh Nam</li>\n<li>20 năm kinh nghiệm lĩnh vực Nội thần kinh</li>\n<li>Công tác tại Khoa Nội Cơ xương khớp - Bệnh viện Chợ Rẫy</li>\n<li>Từng học tập và tu nghiệp tại nước ngoài: Pháp</li>\n</ul>\n<p><strong>Cơ sở được đầu tư trang thiết bị hiện đại theo tiêu chuẩn Mỹ, Châu Âu, Nhật Bản được nhập khẩu từ Mỹ, Nhật, Anh, Đức…</strong></p>\n', '**GIỚI THIỆU CHUNG**\n\n**Phòng khám Đa khoa Victoria Healthcare** thành lập từ năm 2005 đến nay đã trải qua chiều dài kinh nghiệm trong lĩnh vực chăm sóc sức khỏe y tế cao cấp và tạo được sự tín nhiệm cao đối với khách hàng trong khu vực TP Hồ Chí Minh cũng như các tỉnh lân cận. Tại Victoria Healthcare, các Bác sĩ đều nhấn mạnh tầm quan trọng của phương pháp “y học chứng cứ” các tiến trình chẩn đoán và điều trị phải dựa trên xác nhận của y văn hoặc kinh nghiệm điều trị thực tế đã được kiểm chứng, tránh việc lạm dụng thuốc và xét nghiệm. Bác sĩ của Phòng khám phải có nghĩa vụ và trách nhiệm tư vấn thấu đáo cho bệnh nhân cùng gia đình về nguồn gốc, nguyên nhân bệnh, cách chữa trị và phương pháp phòng ngừa. Đó chính là cốt lõi của việc chăm sóc sức khỏe theo tiêu chuẩn Quốc tế.\n\nHệ thống phòng khám Victoria Healthcare có nhiều chi nhánh tại các vị trí giao thông thuận tiện trong thành phố, đầy đủ các chuyên khoa, phục vụ chức năng thăm khám và điều trị ngoại trú.\n\n**Đội ngũ y bác sĩ năng động, tâm huyết, nhiều năm kinh nghiệm, được liên tục đào tạo tại Mỹ, Úc, Nhật… và cam kết thực hành y khoa trên nền tảng Y học chứng cứ.**\n\n*   Bác sĩ chuyên khoa II Nguyễn Thị Băng Hải\n*   40 năm kinh nghiệm lĩnh vực Sản phụ khoa\n*   Từng công tác tại Bệnh viện Đại học Y Dược TP. Hồ Chí Minh, Bệnh viện Đa khoa Vạn Hạnh\n*   Bác sĩ Chuyên khoa I Bùi Bảo Thành\n*   15 năm kinh nghiệm lĩnh vực Nội Tim mạch\n*   Bác sĩ chuyên khoa Nội Tim Mạch - Viện Tim TP. HCM\n*   Thạc sĩ, Bác sĩ Nội trú Nguyễn Cảnh Nam\n*   20 năm kinh nghiệm lĩnh vực Nội thần kinh\n*   Công tác tại Khoa Nội Cơ xương khớp - Bệnh viện Chợ Rẫy \n*   Từng học tập và tu nghiệp tại nước ngoài: Pháp\n\n**Cơ sở được đầu tư trang thiết bị hiện đại theo tiêu chuẩn Mỹ, Châu Âu, Nhật Bản được nhập khẩu từ Mỹ, Nhật, Anh, Đức…**', '2023-12-14 23:16:53', '2023-12-14 23:16:53');

