--
-- Cấu trúc bảng cho bảng `specialties`
--

CREATE TABLE `specialties` (
  `id` int(11) NOT NULL,
  `image` longblob DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `descriptionHTML` text DEFAULT NULL,
  `descriptionMarkdown` text DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Đang đổ dữ liệu cho bảng `specialties`
--

INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(1, , 'Cơ xương khớp', '<h1>Cơ Xương Khớp</h1>\n<h2><strong>Bác sĩ Cơ Xương Khớp giỏi</strong></h2>\n<p>Danh sách các bác sĩ uy tín đầu ngành Cơ Xương Khớp tại Việt Nam:</p>\n<ul>\n<li>Các chuyên gia có quá trình đào tạo bài bản, nhiều kinh nghiệm</li>\n<li>Các giáo sư, phó giáo sư đang trực tiếp nghiên cứu và giảng dạy tại Đại học Y khoa Hà Nội</li>\n<li>Các bác sĩ đã, đang công tác tại các bệnh viện hàng đầu Khoa Cơ Xương Khớp - Bệnh viện Bạch Mai, Bệnh viện Hữu nghị Việt Đức,Bệnh Viện E.</li>\n<li>Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hiệp hội Cơ Xương Khớp, Hội Thấp khớp học,...</li>\n<li>Được nhà nước công nhận các danh hiệu Thầy thuốc Nhân dân, Thầy thuốc Ưu tú, Bác sĩ Cao cấp,...</li>\n</ul>\n<h2><strong>Bệnh Cơ Xương Khớp</strong></h2>\n<ul>\n<li>Gout</li>\n<li>Thoái hóa khớp: khớp gối, cột sống thắt lưng, cột sống cổ</li>\n<li>Viêm khớp dạng thấp, Viêm đa khớp, Viêm gân</li>\n<li>Tràn dịch khớp gối, Tràn dịch khớp háng, Tràn dịch khớp khủy, Tràn dịch khớp vai</li>\n<li>Loãng xương, đau nhức xương</li>\n<li>Viêm xương, gai xương</li>\n<li>Viêm cơ, Teo cơ, chứng đau mỏi cơ</li>\n<li>Yếu cơ, Loạn dưỡng cơ</li>\n<li>Các chấn thương về cơ, xương, khớp</li>\n<li>...</li>\n</ul>\n', '# Cơ Xương Khớp\n## **Bác sĩ Cơ Xương Khớp giỏi**\nDanh sách các bác sĩ uy tín đầu ngành Cơ Xương Khớp tại Việt Nam:\n*   Các chuyên gia có quá trình đào tạo bài bản, nhiều kinh nghiệm\n*   Các giáo sư, phó giáo sư đang trực tiếp nghiên cứu và giảng dạy tại Đại học Y khoa Hà Nội\n*   Các bác sĩ đã, đang công tác tại các bệnh viện hàng đầu Khoa Cơ Xương Khớp - Bệnh viện Bạch Mai, Bệnh viện Hữu nghị Việt Đức,Bệnh Viện E.\n*   Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hiệp hội Cơ Xương Khớp, Hội Thấp khớp học,...\n*   Được nhà nước công nhận các danh hiệu Thầy thuốc Nhân dân, Thầy thuốc Ưu tú, Bác sĩ Cao cấp,...\n\n## **Bệnh Cơ Xương Khớp**\n*   Gout\n*   Thoái hóa khớp: khớp gối, cột sống thắt lưng, cột sống cổ\n*   Viêm khớp dạng thấp, Viêm đa khớp, Viêm gân\n*   Tràn dịch khớp gối, Tràn dịch khớp háng, Tràn dịch khớp khủy, Tràn dịch khớp vai\n*   Loãng xương, đau nhức xương\n*   Viêm xương, gai xương\n*   Viêm cơ, Teo cơ, chứng đau mỏi cơ\n*   Yếu cơ, Loạn dưỡng cơ\n*   Các chấn thương về cơ, xương, khớp\n*   ...', '2023-12-11 15:21:44', '2023-12-11 15:21:44');
INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(3, , 'Thần kinh', '<h1>Thần kinh</h1>\n<h2><strong>Bác sĩ Thần kinh giỏi</strong></h2>\n<p>Danh sách các giáo sư, bác sĩ chuyên khoa Thần kinh giỏi:</p>\n<ul>\n<li>Các giáo sư, bác sĩ uy tín đầu ngành chuyên khoa Thần kinh đã và đang công tác tại các bệnh viện lớn như: Bệnh viện Bạch Mai, Bệnh viện Việt Đức, Bệnh viện 108, Bệnh viện Đại học Y Hà Nội, Bệnh viện 103.</li>\n<li>Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hội Thần kinh Việt Nam, Hội Phẫu thuật Thần kinh...</li>\n<li>Được nhà nước công nhận các danh hiệu Thầy thuốc nhân dân, thầy thuốc ưu tú, bác sĩ cao cấp.</li>\n</ul>\n<h2><strong>Khám bệnh chuyên khoa Thần kinh</strong></h2>\n<ul>\n<li>Bại Não</li>\n<li>Đau đầu, chóng mặt, buồn nôn</li>\n<li>Bệnh Pakison, bệnh tiền đình</li>\n<li>Bị co cơ, căng dây thần kinh</li>\n<li>Động kinh, có những cơn vãng ý thức</li>\n<li>Bị tê bì nửa mặt, chèn dây thần kinh</li>\n<li>Bồn chồn, lo lắng, hồi hộp, chân tay run</li>\n<li>Có dấu hiệu tăng động</li>\n<li>Co rút cổ, đau đầu với mặt, chân tay, vã mồ hôi</li>\n<li>Chấn thương đầu, dây thần kinh</li>\n<li>...</li>\n</ul>\n', '# Thần kinh\n\n## **Bác sĩ Thần kinh giỏi**\n\nDanh sách các giáo sư, bác sĩ chuyên khoa Thần kinh giỏi:\n\n*   Các giáo sư, bác sĩ uy tín đầu ngành chuyên khoa Thần kinh đã và đang công tác tại các bệnh viện lớn như: Bệnh viện Bạch Mai, Bệnh viện Việt Đức, Bệnh viện 108, Bệnh viện Đại học Y Hà Nội, Bệnh viện 103.\n*   Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hội Thần kinh Việt Nam, Hội Phẫu thuật Thần kinh...\n*   Được nhà nước công nhận các danh hiệu Thầy thuốc nhân dân, thầy thuốc ưu tú, bác sĩ cao cấp.\n\n## **Khám bệnh chuyên khoa Thần kinh**\n\n*   Bại Não    \n*   Đau đầu, chóng mặt, buồn nôn  \n*   Bệnh Pakison, bệnh tiền đình   \n*   Bị co cơ, căng dây thần kinh      \n*   Động kinh, có những cơn vãng ý thức   \n*   Bị tê bì nửa mặt, chèn dây thần kinh\n*   Bồn chồn, lo lắng, hồi hộp, chân tay run   \n*   Có dấu hiệu tăng động    \n*   Co rút cổ, đau đầu với mặt, chân tay, vã mồ hôi  \n*   Chấn thương đầu, dây thần kinh\n*   ...', '2023-12-11 15:25:16', '2023-12-11 15:25:16');
INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(4, , 'Tiêu hóa', '<h1>Tiêu hoá</h1>\n<h2><strong>Bác sĩ Chuyên khoa Tiêu hóa</strong></h2>\n<p>Danh sách các bác sĩ Tiêu hóa uy tín đầu ngành tại Việt Nam:</p>\n<ul>\n<li>Các chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện lớn về chuyên ngành Tiêu hóa tại Hà Nội</li>\n<li>Các giáo sư, phó giáo sư là giảng viên Đại học Y khoa Hà Nội</li>\n<li>Các bác sĩ đã, đang công tác tại các bệnh viện hàng đầu như Bệnh viện Bạch Mai, Bệnh Viện Việt Đức, Bệnh Viện Nhi Trung ương, Bệnh viện Y học Cổ truyền Việt Nam...</li>\n<li>Được nhà nước công nhận các danh hiệu Thầy thuốc nhân dân, thầy thuốc ưu tú, bác sĩ cao cấp,...</li>\n</ul>\n<h2><strong>Tư vấn, khám và điều trị các Bệnh Tiêu hóa</strong></h2>\n<ul>\n<li>Ăn uống kém, không ngon</li>\n<li>Rối loạn tiêu hóa, táo bón, trĩ</li>\n<li>Nhiễm vi khuẩn HP (Helicobacter pylori)</li>\n<li>Nội soi dạ dày, đại tràng, tiêu hóa</li>\n<li>Buồn nôn, chướng bụng, đầy bụng ợ chua, đầy hơi</li>\n<li>Co thắt thực quản, Hội chứng ruột kích thích</li>\n<li>Đau bụng, dạ dày, đại tràng, thượng vị</li>\n<li>Viêm đại tràng, dạ dày, tá tràng</li>\n<li>Ung thư dạ dày, U nang tuyến tụy</li>\n<li>Bệnh lý về gan, mật</li>\n<li>...</li>\n</ul>\n', '# Tiêu hoá\n\n## **Bác sĩ Chuyên khoa Tiêu hóa**\n\nDanh sách các bác sĩ Tiêu hóa uy tín đầu ngành tại Việt Nam:\n\n*   Các chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện lớn về chuyên ngành Tiêu hóa tại Hà Nội\n*   Các giáo sư, phó giáo sư là giảng viên Đại học Y khoa Hà Nội\n*   Các bác sĩ đã, đang công tác tại các bệnh viện hàng đầu như Bệnh viện Bạch Mai, Bệnh Viện Việt Đức, Bệnh Viện Nhi Trung ương, Bệnh viện Y học Cổ truyền Việt Nam...\n*   Được nhà nước công nhận các danh hiệu Thầy thuốc nhân dân, thầy thuốc ưu tú, bác sĩ cao cấp,...\n\n## **Tư vấn, khám và điều trị các Bệnh Tiêu hóa**\n\n*   Ăn uống kém, không ngon\n*   Rối loạn tiêu hóa, táo bón, trĩ\n*   Nhiễm vi khuẩn HP (Helicobacter pylori)\n*   Nội soi dạ dày, đại tràng, tiêu hóa\n*   Buồn nôn, chướng bụng, đầy bụng ợ chua, đầy hơi\n*   Co thắt thực quản, Hội chứng ruột kích thích\n*   Đau bụng, dạ dày, đại tràng, thượng vị\n*   Viêm đại tràng, dạ dày, tá tràng\n*   Ung thư dạ dày, U nang tuyến tụy\n*   Bệnh lý về gan, mật\n*   ...', '2023-12-11 15:26:16', '2023-12-11 15:26:16');
INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(5, , 'Tim mạch', '<h1>Tim mạch</h1>\n<h2><strong>Bác sĩ tim mạch giỏi</strong></h2>\n<p>Danh dách các bác sĩ tim mạch uy tín đầu ngành tại Việt Nam:</p>\n<ul>\n<li>Các chuyên gia được đào tạo bài bản về chuyên ngành Tim mạch tại các trường đại học trong nước và quốc tế.</li>\n<li>Các giáo sư, phó giáo sư nghiên cứu và giảng dạy tại Đại học Y Hà Nội</li>\n<li>Các bác sĩ đã, đang công tác tại các bệnh viện hàng đầu như Viện Tim Mạch Quốc Gia, Bệnh viện Bạch Mai, Bệnh viện Việt Đức, Bệnh Viện E, Bệnh Viện Tim Hà Nội</li>\n<li>Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hiệp hội Tim Mạch Việt Nam</li>\n<li>Đạt danh hiệu Thầy thuốc Nhân dân, Thầy thuốc Ưu tú, Bác sĩ Cao cấp,...</li>\n</ul>\n<h2><strong>Khám tư vấn tim mạch</strong></h2>\n<ul>\n<li>Khó thở, Đau ngực, đau tim</li>\n<li>Tăng huyết áp, hạ huyết áp</li>\n<li>Rối loạn mỡ máu, cao huyết áp, chóng mặt</li>\n<li>Bệnh van tim (Hẹp hở van tim), Hẹp động mạch chủ</li>\n<li>Cảm giác hồi hộp, tim đập nhanh</li>\n<li>Tim bẩm sinh, có tiền sử bệnh tim to, tiền sử tai biến</li>\n<li>Đã đặt stent tim, nong động mạch vành</li>\n<li>Giãn tĩnh mạch chân</li>\n<li>...</li>\n</ul>\n', '# Tim mạch\n\n## **Bác sĩ tim mạch giỏi**\n\nDanh dách các bác sĩ tim mạch uy tín đầu ngành tại Việt Nam:\n\n*   Các chuyên gia được đào tạo bài bản về chuyên ngành Tim mạch tại các trường đại học trong nước và quốc tế.\n*   Các giáo sư, phó giáo sư nghiên cứu và giảng dạy tại Đại học Y Hà Nội\n*   Các bác sĩ đã, đang công tác tại các bệnh viện hàng đầu như Viện Tim Mạch Quốc Gia, Bệnh viện Bạch Mai, Bệnh viện Việt Đức, Bệnh Viện E, Bệnh Viện Tim Hà Nội\n*   Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hiệp hội Tim Mạch Việt Nam\n*   Đạt danh hiệu Thầy thuốc Nhân dân, Thầy thuốc Ưu tú, Bác sĩ Cao cấp,...\n\n## **Khám tư vấn tim mạch**\n\n*   Khó thở, Đau ngực, đau tim\n*   Tăng huyết áp, hạ huyết áp\n*   Rối loạn mỡ máu, cao huyết áp, chóng mặt\n*   Bệnh van tim (Hẹp hở van tim), Hẹp động mạch chủ\n*   Cảm giác hồi hộp, tim đập nhanh   \n*   Tim bẩm sinh, có tiền sử bệnh tim to, tiền sử tai biến   \n*   Đã đặt stent tim, nong động mạch vành\n*   Giãn tĩnh mạch chân   \n*   ...', '2023-12-11 15:27:54', '2023-12-11 15:27:54');
INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(6, , 'Da liễu', '<h1>Da liễu</h1>\n<h2><strong>Bác sĩ Chuyên khoa Da liễu</strong></h2>\n<p>HealthyCare cung cấp thông tin và lịch khám của các bác sĩ chuyên khoa da liễu giỏi tại Hà Nội.</p>\n<p>Các chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện lớn tại Hà Nội như: Bệnh viện Da liễu Trung ương, Bệnh viện Da liễu Hà Nội</p>\n<h2><strong>Khám và điều trị</strong></h2>\n<ul>\n<li>Bệnh vẩy nến, Da khô, Ngứa da</li>\n<li>Rám tàn nhang</li>\n<li>Mụn cóc sinh dục</li>\n<li>Nấm cơ thể, Nấm da đầu</li>\n<li>Nấm móng tay, móng chân</li>\n<li>Rụng tóc, hói đầu</li>\n<li>Viêm da dị ứng, Viêm da tiếp xúc, Viêm da tiết bã</li>\n<li>Viêm nang lông</li>\n<li>Xơ cứng bì</li>\n<li>Zona thần kinh</li>\n</ul>\n', '# Da liễu\n\n## **Bác sĩ Chuyên khoa Da liễu**\n\nHealthyCare cung cấp thông tin và lịch khám của các bác sĩ chuyên khoa da liễu giỏi tại Hà Nội.\n\nCác chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện lớn tại Hà Nội như: Bệnh viện Da liễu Trung ương, Bệnh viện Da liễu Hà Nội\n\n## **Khám và điều trị**\n\n*   Bệnh vẩy nến, Da khô, Ngứa da\n*   Rám tàn nhang\n*   Mụn cóc sinh dục\n*   Nấm cơ thể, Nấm da đầu\n*   Nấm móng tay, móng chân\n*   Rụng tóc, hói đầu\n*   Viêm da dị ứng, Viêm da tiếp xúc, Viêm da tiết bã\n*   Viêm nang lông\n*   Xơ cứng bì\n*   Zona thần kinh', '2023-12-11 15:29:17', '2023-12-11 15:29:17');
INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(8, , 'Thẩm mỹ', '<h1>Da liễu thẩm mỹ</h1>\n<h2><strong>Bác sĩ Chuyên khoa Da liễu thẩm mỹ</strong></h2>\n<p>HealthyCare cung cấp thông tin và lịch khám của các bác sĩ chuyên khoa da liễu thẩm mỹ giỏi.</p>\n<ul>\n<li>Các chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện lớn tại Hà Nội như: Bệnh viện Da liễu Trung ương, Bệnh viện Da liễu Hà Nội</li>\n</ul>\n<h2><strong>Khám và điều trị</strong></h2>\n<ul>\n<li>Bớt sắc tố: Nốt, mảng tăng sắc tố khu trú hoặc lan tỏa trên cơ thể, bề mặt phẳng, màu nâu, đen , xanh. Không đau , không ngứa rát.</li>\n<li>Nám da: Dát tăng sắc tố màu nâu, xanh đen đối xứng 2 bên mặt, bằng phẳng, bờ không đều, không teo da, không ngứa.</li>\n<li>Trứng cá: Mụn nhân trắng đen, mụn viêm , mụn nang, mụn bọc</li>\n<li>Sẹo lõm: Tổn thương lõm sâu xuống dưới bề mặt da, màu đậm hoặc cùng màu da, không đau. Sẹo đáy nhọn, sẹo đáy hộp, sẹo đáy tròn</li>\n<li>Sẹo lồi: Tổn thương nổi gồ trên bề mặt da, không đau, màu trùng màu da hoặc đậm hơn</li>\n<li>Lão hóa da: Da bị chảy xệ, trùng nhão không được săn chắc. Nhiều nếp nhăn vùng trán, đuôi mắt, rãnh mũi má</li>\n</ul>\n', '# Da liễu thẩm mỹ\n\n## **Bác sĩ Chuyên khoa Da liễu thẩm mỹ**\n\nHealthyCare cung cấp thông tin và lịch khám của các bác sĩ chuyên khoa da liễu thẩm mỹ giỏi.\n\n*   Các chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện lớn tại Hà Nội như: Bệnh viện Da liễu Trung ương, Bệnh viện Da liễu Hà Nội\n\n## **Khám và điều trị**\n\n*   Bớt sắc tố: Nốt, mảng tăng sắc tố khu trú hoặc lan tỏa trên cơ thể, bề mặt phẳng, màu nâu, đen , xanh. Không đau , không ngứa rát.\n*   Nám da: Dát tăng sắc tố màu nâu, xanh đen đối xứng 2 bên mặt, bằng phẳng, bờ không đều, không teo da, không ngứa.\n*   Trứng cá: Mụn nhân trắng đen, mụn viêm , mụn nang, mụn bọc\n*   Sẹo lõm: Tổn thương lõm sâu xuống dưới bề mặt da, màu đậm hoặc cùng màu da, không đau. Sẹo đáy nhọn, sẹo đáy hộp, sẹo đáy tròn\n*   Sẹo lồi: Tổn thương nổi gồ trên bề mặt da, không đau, màu trùng màu da hoặc đậm hơn\n*   Lão hóa da: Da bị chảy xệ, trùng nhão không được săn chắc. Nhiều nếp nhăn vùng trán, đuôi mắt, rãnh mũi má', '2023-12-11 15:31:30', '2023-12-11 15:31:30');
INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(9, , 'Hô hấp', '<h2><strong>Bác sĩ Chuyên khoa Hô hấp - Phổi</strong></h2>\n<p><strong>Danh sách các bác sĩ chuyên khoa Hô hấp - Phổi giỏi:</strong></p>\n<ul>\n<li>Các chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện, phòng khám lớn như: Bệnh viện Đại học Y dược, Phòng khám Phổi Sài Gòn, Bệnh viện Phổi Trung ương,...</li>\n<li>Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hội Phổi Việt Nam, Hội Hô Hấp Việt Nam...</li>\n</ul>\n<p><strong>Khám và điều trị</strong></p>\n<ul>\n<li>Lao</li>\n<li>Lao kháng thuốc</li>\n<li>Hen</li>\n<li>COPD</li>\n<li>Các bệnh Phổi nghề nghiệp</li>\n<li>Các bệnh hô hấp</li>\n</ul>\n', '## **Bác sĩ Chuyên khoa Hô hấp - Phổi**\n\n**Danh sách các bác sĩ chuyên khoa Hô hấp - Phổi giỏi:**\n\n*   Các chuyên gia có quá trình đào tạo bài bản, kinh nghiệm công tác tại các bệnh viện, phòng khám lớn như: Bệnh viện Đại học Y dược, Phòng khám Phổi Sài Gòn, Bệnh viện Phổi Trung ương,...\n*   Là thành viên hoặc lãnh đạo các tổ chức chuyên môn như: Hội Phổi Việt Nam, Hội Hô Hấp Việt Nam...\n\n**Khám và điều trị**\n\n*   Lao\n*   Lao kháng thuốc\n*   Hen\n*   COPD\n*   Các bệnh Phổi nghề nghiệp\n*   Các bệnh hô hấp', '2023-12-11 15:32:48', '2023-12-11 15:32:48');
INSERT INTO `specialties` (`id`, `image`, `name`, `descriptionHTML`, `descriptionMarkdown`, `createdAt`, `updatedAt`) VALUES
(10, , 'Sức khỏe tâm thần', '<h1>Sức khỏe tâm thần</h1>\n<h2><strong>Bác sĩ về Sức khỏe Tâm thần giỏi</strong></h2>\n<p><strong>Danh sách các giáo sư, bác sĩ chuyên khoa Sức khỏe tâm thần giỏi:</strong></p>\n<ul>\n<li>Các giáo sư, bác sĩ uy tín đầu ngành chuyên khoa Sức khỏe tâm thần đã và đang công tác tại các bệnh viện lớn như: Bệnh viện Tâm thần Trung ương, Bệnh viện Chợ Rẫy, Bệnh viện Lão khoa...</li>\n<li>Được nhà nước công nhận các danh hiệu Thầy thuốc nhân dân, thầy thuốc ưu tú, bác sĩ cao cấp.</li>\n</ul>\n<p><strong>Bác sĩ khám -Tư vấn - Điều trị</strong></p>\n<ul>\n<li>Mất ngủ, Rối loạn giấc ngủ</li>\n<li>Trầm cảm, Căng thẳng, stress</li>\n<li>Tâm thần phân liệt, Bệnh hoang tưởng</li>\n<li>Rối loạn cảm xúc , Rối loạn căng thẳng sau chấn thương tâm lý</li>\n<li>Rối loạn lo âu, Rối loạn lưỡng cực, Rối loạn nhân cách</li>\n<li>Tư vấn và tạo điều kiện cho bệnh nhân tái thích ứng xã hội</li>\n</ul>\n<p><strong>Một số triệu chứng, biểu hiện</strong></p>\n<ul>\n<li>Ảo giác, Hoang tưởng, Nói cười một mình</li>\n<li>Bi quan, Bồn chồn, Buồn rầu, Hoảng hốt</li>\n<li>Khó tập trung tâm trí, Nhầm lẫn tư duy</li>\n<li>Lo âu, Lo lắng</li>\n<li>Rối loạn giấc ngủ</li>\n<li>Sợ hãi, Sợ một mình, Sợ nơi đông người</li>\n<li>Xa lánh mọi người, Ý nghĩ kì lạ</li>\n</ul>\n', '# Sức khỏe tâm thần\n\n## **Bác sĩ về Sức khỏe Tâm thần giỏi**\n\n**Danh sách các giáo sư, bác sĩ chuyên khoa Sức khỏe tâm thần giỏi:**\n\n*   Các giáo sư, bác sĩ uy tín đầu ngành chuyên khoa Sức khỏe tâm thần đã và đang công tác tại các bệnh viện lớn như: Bệnh viện Tâm thần Trung ương, Bệnh viện Chợ Rẫy, Bệnh viện Lão khoa...\n*   Được nhà nước công nhận các danh hiệu Thầy thuốc nhân dân, thầy thuốc ưu tú, bác sĩ cao cấp.\n\n**Bác sĩ khám -Tư vấn - Điều trị**\n\n*   Mất ngủ, Rối loạn giấc ngủ\n*   Trầm cảm, Căng thẳng, stress\n*   Tâm thần phân liệt, Bệnh hoang tưởng\n*   Rối loạn cảm xúc , Rối loạn căng thẳng sau chấn thương tâm lý \n*   Rối loạn lo âu, Rối loạn lưỡng cực, Rối loạn nhân cách\n*   Tư vấn và tạo điều kiện cho bệnh nhân tái thích ứng xã hội\n\n**Một số triệu chứng, biểu hiện**\n\n*   Ảo giác, Hoang tưởng, Nói cười một mình\n*   Bi quan, Bồn chồn, Buồn rầu, Hoảng hốt\n*   Khó tập trung tâm trí, Nhầm lẫn tư duy\n*   Lo âu, Lo lắng\n*   Rối loạn giấc ngủ\n*   Sợ hãi, Sợ một mình, Sợ nơi đông người\n*   Xa lánh mọi người, Ý nghĩ kì lạ', '2023-12-11 15:34:44', '2023-12-11 15:34:44');

